{
  "name": "demo-api",
  "version": "0.1.0",
  "private": true,
  "description": "Backend for demo: mounts @sentropic/chat-server canonical routes over an in-memory adapter.",
  "type": "module",
  "license": "MIT",
  "main": "./dist/server.js",
  "scripts": {
    "dev": "node --experimental-strip-types src/server.ts",
    "build": "tsc -p tsconfig.json",
    "start": "node dist/server.js",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "dependencies": {
    "@sentropic/chat-server": "^0.4.0",
    "@hono/node-server": "^2.0.0",
    "hono": "^4.10.7"
  },
  "devDependencies": {
    "@types/node": "^22.10.10",
    "typescript": "^5.4.5"
  }
}

/**
 * demo backend.
 *
 * Mounts the published @sentropic/chat-server CANONICAL routes
 * (POST/GET /chat/sessions/:id/{messages,bootstrap}, GET /chat/sessions/:id/stream)
 * over its OFFLINE in-memory adapter. No Postgres, no provider key required: the
 * in-memory deps reply with a deterministic message so a chat round-trip works out of
 * the box. Switch to a real provider by extending these deps (see README).
 */

import { serve } from '@hono/node-server';
import { Hono } from 'hono';
import { createChatServer, createInMemoryChatServerDeps } from '@sentropic/chat-server';

const PORT = Number(process.env.PORT ?? 9211);
const ASSISTANT_REPLY = 'Hello from demo (deterministic offline reply).';

// The chat wire server: canonical routes consumed by @sentropic/chat-ui's
// createDefaultTransport(baseUrl). Offline in-memory adapter = deterministic reply.
const chat = createChatServer(
  createInMemoryChatServerDeps({ assistantReply: ASSISTANT_REPLY }),
  { routes: 'canonical' },
);

const app = new Hono();

// Allow the UI (served on a different port) to call the chat routes + read SSE.
app.use('*', async (c, next) => {
  c.header('access-control-allow-origin', '*');
  c.header('access-control-allow-headers', 'content-type, x-app-locale');
  c.header('access-control-allow-methods', 'GET, POST, OPTIONS');
  if (c.req.method === 'OPTIONS') {
    return c.body(null, 204);
  }
  await next();
});

app.get('/health', (c) => c.json({ status: 'ok' }));

// Mount the chat-server routes at the root: the transport hits /chat/sessions/:id/*.
app.route('/', chat);

serve({ fetch: app.fetch, port: PORT }, (info) => {
  // eslint-disable-next-line no-console
  console.log(`demo backend listening on http://localhost:${info.port}`);
});

import { mount } from 'svelte';
// Published design surface (D4): theme CSS variables + tokens.
import '@sentropic/design-system-themes/css/sent-tech.css';
import App from './App.svelte';

const target = document.getElementById('app');
if (!target) {
  throw new Error('Missing #app mount target');
}

export default mount(App, { target });

/// <reference types="svelte" />
/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_API_BASE_URL?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

import { vitePreprocess } from '@sveltejs/vite-plugin-svelte';

/** @type {import('@sveltejs/vite-plugin-svelte').Config} */
export default {
  preprocess: vitePreprocess(),
};

import { defineConfig } from 'vite';
import { svelte } from '@sveltejs/vite-plugin-svelte';

// The backend base URL is injected at build/dev time via VITE_API_BASE_URL
// (see .env.example), aligned with the api service port.
export default defineConfig({
  plugins: [svelte()],
  server: {
    host: '0.0.0.0',
    port: 5411,
  },
  preview: {
    host: '0.0.0.0',
    port: 5411,
  },
});
